            (mb_config.torque_limit_nm <= 0.0) ||
            (!isfinite(mb_config.max_wheel_speed_rad_s)) ||
            (mb_config.max_wheel_speed_rad_s <= 0.0) ||
            (mb_config.settle_cycles < 1U) || (mb_config.settle_cycles > 20U))
            fault = 1;
    }

    if (fault) {
        mb_state.mode = MB_FAULT;
        mb_state.settled = 0U;
        mb_state.target_initialized = 0;
        mb_state.commanded_target_nms = (adcs_vec3_t){0, 0, 0};
        mb_state.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
        mb_output.mode = MB_FAULT;
        mb_output.settled = 0U;
        mb_output.saturation_mask = 0U;
        mb_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
        mb_output.commanded_target_nms = (adcs_vec3_t){0, 0, 0};
        mb_output.error_nms = (adcs_vec3_t){0, 0, 0};
        mb_output.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
        mb_output.torque_nm = (adcs_vec3_t){0, 0, 0};
        return;
    }

    if (mb_input.enable == 0) {
        mb_state.mode = MB_OFF;
        mb_state.settled = 0U;
        mb_state.target_initialized = 0;
        mb_state.commanded_target_nms = (adcs_vec3_t){0, 0, 0};
        mb_state.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
        mb_output.mode = MB_OFF;
        mb_output.settled = 0U;
        mb_output.saturation_mask = 0U;
        mb_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
        mb_output.commanded_target_nms = (adcs_vec3_t){0, 0, 0};
        mb_output.error_nms = (adcs_vec3_t){0, 0, 0};
        mb_output.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
        mb_output.torque_nm = (adcs_vec3_t){0, 0, 0};
        return;
    }

    (void)adcs_wheel_momentum(mb_input.wheels, mb_input.wheel_count, &momentum);

    if (!mb_state.target_initialized) {
        mb_state.commanded_target_nms = momentum;
        mb_state.target_initialized = 1;
        mb_state.mode = MB_RAMP;
        mb_state.settled = 0U;
        mb_state.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
    }

    {
        double tvals[3] = {mb_config.target_nms.x, mb_config.target_nms.y, mb_config.target_nms.z};
        double rvals[3] = {mb_state.commanded_target_nms.x, mb_state.commanded_target_nms.y,
                           mb_state.commanded_target_nms.z};
        double s = mb_config.target_slew_nms_per_cycle;
        for (i = 0; i < 3; i++) {
            double d = tvals[i] - rvals[i];
            if (d > s)
                d = s;
            else if (d < -s)
                d = -s;
            else {
                /* within slew band */
            }
            rvals[i] += d;
        }
        {
            adcs_vec3_t ramp = (adcs_vec3_t){rvals[0], rvals[1], rvals[2]};
            if ((ramp.x != mb_state.commanded_target_nms.x) ||
                (ramp.y != mb_state.commanded_target_nms.y) ||
                (ramp.z != mb_state.commanded_target_nms.z))
                target_changed = 1;
            mb_state.commanded_target_nms = ramp;
        }
    }

    if (target_changed) {
        mb_state.mode = MB_RAMP;
        mb_state.settled = 0U;
    } else {
        if ((mb_state.mode == MB_RAMP) &&
            (mb_state.commanded_target_nms.x == mb_config.target_nms.x) &&
            (mb_state.commanded_target_nms.y == mb_config.target_nms.y) &&
            (mb_state.commanded_target_nms.z == mb_config.target_nms.z)) {
            mb_state.mode = MB_BIAS;
            mb_state.settled = 0U;
        }
    }

    error = adcs_vec3_sub(&momentum, &mb_state.commanded_target_nms);
    err_vals[0] = error.x;
    err_vals[1] = error.y;
    err_vals[2] = error.z;
    err_norm = adcs_vec3_norm(&error);

    if (mb_state.mode == MB_HOLD) {
        if (err_norm >= mb_config.exit_error_nms) {
            mb_state.mode = MB_BIAS;
            mb_state.settled = 0U;
        }
    } else if (mb_state.mode == MB_BIAS) {
        if (err_norm <= mb_config.enter_error_nms) {
            mb_state.settled += 1U;
            if (mb_state.settled >= mb_config.settle_cycles)
                mb_state.mode = MB_HOLD;
        } else {
            mb_state.settled = 0U;
        }
    } else {
        mb_state.settled = 0U;
    }

    old_int[0] = mb_state.integral_error_nms_s.x;
    old_int[1] = mb_state.integral_error_nms_s.y;
    old_int[2] = mb_state.integral_error_nms_s.z;
    if (mb_state.mode == MB_RAMP) {
        prop_int[0] = 0.0;
        prop_int[1] = 0.0;
        prop_int[2] = 0.0;
    } else {
        for (i = 0; i < 3; i++) {
            double p = old_int[i] + err_vals[i] * dt;
            if (p > mb_config.integral_limit_nms_s)
                p = mb_config.integral_limit_nms_s;
            else if (p < -mb_config.integral_limit_nms_s)
                p = -mb_config.integral_limit_nms_s;
            else {
                /* within integral limit */
            }
            prop_int[i] = p;
        }
    }

    for (i = 0; i < 3; i++) {
        double ki = (mb_state.mode == MB_RAMP) ? 0.0 : mb_config.ki_s2_inv;
        torque_vals[i] = -mb_config.kp_s_inv * err_vals[i] - ki * prop_int[i];
    }

    if (fabs(torque_vals[0]) > mb_config.torque_limit_nm)
        mask |= 1U;
    if (fabs(torque_vals[1]) > mb_config.torque_limit_nm)
        mask |= 2U;
    if (fabs(torque_vals[2]) > mb_config.torque_limit_nm)
        mask |= 4U;

    for (i = 0; i < 3; i++) {
        double limit = mb_config.torque_limit_nm;
        double ki = (mb_state.mode == MB_RAMP) ? 0.0 : mb_config.ki_s2_inv;
        if ((fabs(torque_vals[i]) > limit) && (ki > 0.0)) {
            int driven = 0;
            if ((prop_int[i] > old_int[i]) && (torque_vals[i] < 0.0))
                driven = 1;
            if ((prop_int[i] < old_int[i]) && (torque_vals[i] > 0.0))
                driven = 1;
            if (driven) {
                prop_int[i] = old_int[i];
                torque_vals[i] = -mb_config.kp_s_inv * err_vals[i] - ki * old_int[i];
            }
        }
    }

    for (i = 0; i < 3; i++) {
        double limit = mb_config.torque_limit_nm;
        if (torque_vals[i] > limit)
            torque_vals[i] = limit;
        else if (torque_vals[i] < -limit)
            torque_vals[i] = -limit;
        else {
            /* within torque limit */
        }
    }
    torque = (adcs_vec3_t){torque_vals[0], torque_vals[1], torque_vals[2]};
    proposed_integral = (adcs_vec3_t){prop_int[0], prop_int[1], prop_int[2]};

    mb_state.integral_error_nms_s = proposed_integral;

    mb_output.mode = mb_state.mode;
    mb_output.settled = mb_state.settled;
    mb_output.saturation_mask = mask;
    mb_output.momentum_nms = momentum;
    mb_output.commanded_target_nms = mb_state.commanded_target_nms;
    mb_output.error_nms = error;
    mb_output.integral_error_nms_s = proposed_integral;
    mb_output.torque_nm = torque;

    return;
}

candidates.raw:
mb_output_t out_local;
mb_mode_t next_mode;
adcs_vec3_t momentum;
adcs_vec3_t prev_integral;
double err_vals[3], prop_int[3], tor[3], pre_tor[3];
double int_prev[3];
size_t i;
unint32 mask = 0U;
int changed = 0;
int fault = 0;
double error_norm;

out_local.mode = MB_OFF;
out_local.settled = 0U;
out_local.saturation_mask = 0U;
out_local.momentum_nms = (adcs_vec3_t){0, 0, 0};
out_local.commanded_target_nms = (adcs_vec3_t){0, 0, 0};
out_local.error_nms = (adcs_vec3_t){0, 0, 0};
out_local.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
out_local.torque_nm = (adcs_vec3_t){0, 0, 0};

/* validation */
if (mb_input.wheels == NULL || mb_input.wheel_count != 4U) {
    fault = 1;
}
if (mb_input.enable != 0 && mb_input.enable != 1) {
    fault = 1;
}
if (!isfinite(mb_config.target_slew_nms_per_cycle) ||
    mb_config.target_slew_nms_per_cycle <= 0.0) {
    fault = 1;
}
if (!isfinite(mb_config.dt_s) || mb_config.dt_s <= 0.0) {
    fault = 1;
}
if (!isfinite(mb_config.integral_limit_nms_s) ||
    mb_config.integral_limit_nms_s <= 0.0) {
    fault = 1;
}
if (!isfinite(mb_config.torque_limit_nm) || mb_config.torque_limit_nm <= 0.0) {
    fault = 1;
}
if (!isfinite(mb_config.max_wheel_speed_rad_s) ||
    mb_config.max_wheel_speed_rad_s <= 0.0) {
    fault = 1;
}
if (mb_config.settle_cycles < 1U || mb_config.settle_cycles > 20U) {
    fault = 1;
}
if (!isfinite(mb_config.kp_s_inv) || mb_config.kp_s_inv < 0.0) {
    fault = 1;
}
if (!isfinite(mb_config.ki_s2_inv) || mb_config.ki_s2_inv < 0.0) {
    fault = 1;
}
if (!isfinite(mb_config.enter_error_nms) || !isfinite(mb_config.exit_error_nms) ||
    mb_config.enter_error_nms < 0.0 ||
    mb_config.enter_error_nms >= mb_config.exit_error_nms) {
    fault = 1;
}
if (!isfinite(mb_config.target_nms.x) || !isfinite(mb_config.target_nms.y) ||
    !isfinite(mb_config.target_nms.z)) {
    fault = 1;
}
if (!fault) {
    for (i = 0; i < 4U; i++) {
        if (!isfinite(mb_input.wheels[i].speed_rad_s) ||
            !isfinite(mb_input.wheels[i].inertia_kg_m2) ||
            mb_input.wheels[i].inertia_kg_m2 < 0.0) {
            fault = 1;
            break;
        }
        if (fabs(mb_input.wheels[i].speed_rad_s) > mb_config.max_wheel_speed_rad_s) {
            fault = 1;
            break;
        }
    }
}

/* disable resets */
if (mb_input.enable == 0) {
    mb_state.mode = MB_OFF;
    mb_state.settled = 0U;
    mb_state.target_initialized = 0;
    mb_state.commanded_target_nms = (adcs_vec3_t){0, 0, 0};
    mb_state.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
    out_local.mode = MB_OFF;
    out_local.settled = 0U;
    out_local.saturation_mask = 0U;
    mb_output = out_local;
    return;
}

/* fault latches */
if (fault) {
    mb_state.mode = MB_FAULT;
    mb_state.settled = 0U;
    mb_state.target_initialized = 0;
    mb_state.commanded_target_nms = (adcs_vec3_t){0, 0, 0};
    mb_state.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
    out_local.mode = MB_FAULT;
    out_local.settled = 0U;
    out_local.saturation_mask = 0U;
    mb_output = out_local;
    return;
}

/* momentum */
if (adcs_wheel_momentum(mb_input.wheels, mb_input.wheel_count, &momentum) != ADCS_OK) {
    mb_state.mode = MB_FAULT;
    mb_state.settled = 0U;
    mb_state.target_initialized = 0;
    mb_state.commanded_target_nms = (adcs_vec3_t){0, 0, 0};
    mb_state.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
    out_local.mode = MB_FAULT;
    out_local.settled = 0U;
    out_local.saturation_mask = 0U;
    mb_output = out_local;
    return;
}
out_local.momentum_nms = momentum;

/* target init */
if (!mb_state.target_initialized) {
    mb_state.commanded_target_nms = momentum;
    mb_state.target_initialized = 1;
    mb_state.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
    mb_state.settled = 0U;
    mb_state.mode = MB_RAMP;
    changed = 1;
}
next_mode = mb_state.mode;
prev_integral = mb_state.integral_error_nms_s;
int_prev[0] = prev_integral.x;
int_prev[1] = prev_integral.y;
int_prev[2] = prev_integral.z;

/* target slew per axis */
{
    double cmd[3], tgt[3], d[3], step;
    cmd[0] = mb_state.commanded_target_nms.x;
    cmd[1] = mb_state.commanded_target_nms.y;
    cmd[2] = mb_state.commanded_target_nms.z;
    tgt[0] = mb_config.target_nms.x;
    tgt[1] = mb_config.target_nms.y;
    tgt[2] = mb_config.target_nms.z;
    step = mb_config.target_slew_nms_per_cycle;
    for (i = 0; i < 3U; i++) {
        d[i] = tgt[i] - cmd[i];
        if (d[i] > step) {
            cmd[i] += step;
            changed = 1;
        } else if (d[i] < -step) {
            cmd[i] -= step;
            changed = 1;
        } else {
            cmd[i] = tgt[i];
        }
    }
    mb_state.commanded_target_nms = (adcs_vec3_t){cmd[0], cmd[1], cmd[2]};
}

/* mode transitions */
if (changed) {
    next_mode = MB_RAMP;
    mb_state.settled = 0U;
    mb_state.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
    prev_integral = (adcs_vec3_t){0, 0, 0};
    int_prev[0] = 0.0;
    int_prev[1] = 0.0;
    int_prev[2] = 0.0;
} else if (next_mode == MB_RAMP) {
    next_mode = MB_BIAS;
    mb_state.settled = 0U;
}

/* error */
err_vals[0] = momentum.x - mb_state.commanded_target_nms.x;
err_vals[1] = momentum.y - mb_state.commanded_target_nms.y;
err_vals[2] = momentum.z - mb_state.commanded_target_nms.z;
error_norm = sqrt(err_vals[0] * err_vals[0] + err_vals[1] * err_vals[1] +
                  err_vals[2] * err_vals[2]);

/* HOLD exit */
if (next_mode == MB_HOLD) {
    if (error_norm >= mb_config.exit_error_nms) {
        next_mode = MB_BIAS;
        mb_state.settled = 0U;
    }
}

/* BIAS settle */
if (next_mode == MB_BIAS) {
    if (error_norm <= mb_config.enter_error_nms) {
        if (mb_state.settled < 0xFFFFFFFFU) {
            mb_state.settled++;
        }
    } else {
        mb_state.settled = 0U;
    }
    if (mb_state.settled >= mb_config.settle_cycles) {
        next_mode = MB_HOLD;
    }
}

/* proposed integral */
for (i = 0; i < 3U; i++) {
    prop_int[i] = int_prev[i] + err_vals[i] * mb_config.dt_s;
    if (prop_int[i] > mb_config.integral_limit_nms_s) {
        prop_int[i] = mb_config.integral_limit_nms_s;
    } else if (prop_int[i] < -mb_config.integral_limit_nms_s) {
        prop_int[i] = -mb_config.integral_limit_nms_s;
    }
}

/* torque per mode */
if (next_mode == MB_RAMP) {
    for (i = 0; i < 3U; i++) {
        tor[i] = -mb_config.kp_s_inv * err_vals[i];
        pre_tor[i] = tor[i];
    }
} else {
    for (i = 0; i < 3U; i++) {
        pre_tor[i] = -mb_config.kp_s_inv * err_vals[i] -
                     mb_config.ki_s2_inv * prop_int[i];
        tor[i] = pre_tor[i];
    }
}

/* saturation mask & freeze */
for (i = 0; i < 3U; i++) {
    if (fabs(pre_tor[i]) > mb_config.torque_limit_nm) {
        mask |= (unint32)(1U << i);
        if (next_mode != MB_RAMP) {
            double new_tor = -mb_config.kp_s_inv * err_vals[i] -
                             mb_config.ki_s2_inv * prop_int[i];
            double old_tor = -mb_config.kp_s_inv * err_vals[i] -
                             mb_config.ki_s2_inv * int_prev[i];
            if (fabs(new_tor) > fabs(old_tor) &&
                ((new_tor > 0.0 && old_tor >= 0.0) ||
                 (new_tor < 0.0 && old_tor <= 0.0))) {
                tor[i] = old_tor;
                prop_int[i] = int_prev[i];
            }
        }
    }
}

/* limit torque independently */
for (i = 0; i < 3U; i++) {
    if (tor[i] > mb_config.torque_limit_nm) {
        tor[i] = mb_config.torque_limit_nm;
    } else if (tor[i] < -mb_config.torque_limit_nm) {
        tor[i] = -mb_config.torque_limit_nm;
    }
}

/* clear integral in RAMP, else commit */
if (next_mode == MB_RAMP) {
    mb_state.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
} else {
    mb_state.integral_error_nms_s = (adcs_vec3_t){prop_int[0], prop_int[1], prop_int[2]};
}

/* publish */
mb_state.mode = next_mode;
out_local.mode = next_mode;
out_local.settled = mb_state.settled;
out_local.commanded_target_nms = mb_state.commanded_target_nms;
out_local.error_nms = (adcs_vec3_t){err_vals[0], err_vals[1], err_vals[2]};
out_local.integral_error_nms_s = mb_state.integral_error_nms_s;
out_local.torque_nm = (adcs_vec3_t){tor[0], tor[1], tor[2]};
out_local.saturation_mask = mask;
mb_output = out_local;

