        mb_output.settled = 0U;
        mb_output.saturation_mask = 0U;
        mb_output.momentum_nms = (adcs_vec3_t){0.0, 0.0, 0.0};
        mb_output.commanded_target_nms = (adcs_vec3_t){0.0, 0.0, 0.0};
        mb_output.error_nms = (adcs_vec3_t){0.0, 0.0, 0.0};
        mb_output.integral_error_nms_s = (adcs_vec3_t){0.0, 0.0, 0.0};
        mb_output.torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
        return;
    }

    if (mb_input.enable == 0) {
        mb_state.mode = MB_OFF;
        mb_state.settled = 0U;
        mb_state.target_initialized = 0;
        mb_state.integral_error_nms_s = (adcs_vec3_t){0.0, 0.0, 0.0};
        mb_output.mode = MB_OFF;
        mb_output.settled = 0U;
        mb_output.saturation_mask = 0U;
        mb_output.momentum_nms = momentum;
        mb_output.commanded_target_nms = mb_state.commanded_target_nms;
        mb_output.error_nms = (adcs_vec3_t){0.0, 0.0, 0.0};
        mb_output.integral_error_nms_s = (adcs_vec3_t){0.0, 0.0, 0.0};
        mb_output.torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
        return;
    }

    if (!mb_state.target_initialized) {
        mb_state.commanded_target_nms = momentum;
        mb_state.target_initialized = 1;
        mb_state.integral_error_nms_s = (adcs_vec3_t){0.0, 0.0, 0.0};
        mb_state.mode = MB_RAMP;
        mb_state.settled = 0U;
    }

    old_target[0] = mb_state.commanded_target_nms.x;
    old_target[1] = mb_state.commanded_target_nms.y;
    old_target[2] = mb_state.commanded_target_nms.z;
    new_target[0] = mb_config.target_nms.x;
    new_target[1] = mb_config.target_nms.y;
    new_target[2] = mb_config.target_nms.z;

    if ((new_target[0] != old_target[0]) || (new_target[1] != old_target[1]) ||
        (new_target[2] != old_target[2])) {
        target_changed = 1;
    }

    if (target_changed) {
        mb_state.mode = MB_RAMP;
    }

    if (mb_state.mode == MB_RAMP) {
        double diff[3];
        double cmdt[3];
        double mstep = slew;

        cmdt[0] = mb_state.commanded_target_nms.x;
        cmdt[1] = mb_state.commanded_target_nms.y;
        cmdt[2] = mb_state.commanded_target_nms.z;
        diff[0] = new_target[0] - cmdt[0];
        diff[1] = new_target[1] - cmdt[1];
        diff[2] = new_target[2] - cmdt[2];
        for (i = 0; i < 3; i++) {
            if (diff[i] > mstep)
                cmdt[i] += mstep;
            else if (diff[i] < -mstep)
                cmdt[i] -= mstep;
            else
                cmdt[i] = new_target[i];
        }
        mb_state.commanded_target_nms = (adcs_vec3_t){cmdt[0], cmdt[1], cmdt[2]};

        if ((mb_state.commanded_target_nms.x == new_target[0]) &&
            (mb_state.commanded_target_nms.y == new_target[1]) &&
            (mb_state.commanded_target_nms.z == new_target[2])) {
            mb_state.mode = MB_BIAS;
            mb_state.settled = 0U;
        }
    }

    errv[0] = momentum.x - mb_state.commanded_target_nms.x;
    errv[1] = momentum.y - mb_state.commanded_target_nms.y;
    errv[2] = momentum.z - mb_state.commanded_target_nms.z;

    integ[0] = mb_state.integral_error_nms_s.x;
    integ[1] = mb_state.integral_error_nms_s.y;
    integ[2] = mb_state.integral_error_nms_s.z;

    if (mb_state.mode == MB_RAMP) {
        integ[0] = 0.0;
        integ[1] = 0.0;
        integ[2] = 0.0;
        torq[0] = -mb_config.kp_s_inv * errv[0];
        torq[1] = -mb_config.kp_s_inv * errv[1];
        torq[2] = -mb_config.kp_s_inv * errv[2];
        prop_torq[0] = torq[0];
        prop_torq[1] = torq[1];
        prop_torq[2] = torq[2];
    } else {
        double prop_integ[3];
        prop_integ[0] = integ[0] + errv[0] * dt;
        prop_integ[1] = integ[1] + errv[1] * dt;
        prop_integ[2] = integ[2] + errv[2] * dt;
        prop_integ[0] = ADCS_CLAMP(prop_integ[0], -mb_config.integral_limit_nms_s,
                                   mb_config.integral_limit_nms_s);
        prop_integ[1] = ADCS_CLAMP(prop_integ[1], -mb_config.integral_limit_nms_s,
                                   mb_config.integral_limit_nms_s);
        prop_integ[2] = ADCS_CLAMP(prop_integ[2], -mb_config.integral_limit_nms_s,
                                   mb_config.integral_limit_nms_s);

        prop_torq[0] = -mb_config.kp_s_inv * errv[0] - mb_config.ki_s2_inv * prop_integ[0];
        prop_torq[1] = -mb_config.kp_s_inv * errv[1] - mb_config.ki_s2_inv * prop_integ[1];
        prop_torq[2] = -mb_config.kp_s_inv * errv[2] - mb_config.ki_s2_inv * prop_integ[2];

        integ[0] = prop_integ[0];
        integ[1] = prop_integ[1];
        integ[2] = prop_integ[2];

        torq[0] = prop_torq[0];
        torq[1] = prop_torq[1];
        torq[2] = prop_torq[2];

        if (fabs(prop_torq[0]) > mb_config.torque_limit_nm)
            mask |= (uint32_t)(1U << 0);
        if (fabs(prop_torq[1]) > mb_config.torque_limit_nm)
            mask |= (uint32_t)(1U << 1);
        if (fabs(prop_torq[2]) > mb_config.torque_limit_nm)
            mask |= (uint32_t)(1U << 2);

        if (fabs(prop_torq[0]) > mb_config.torque_limit_nm) {
            double dir = (prop_torq[0] > 0.0) ? 1.0 : -1.0;
            double delta = integ[0] - mb_state.integral_error_nms_s.x;
            if ((-mb_config.ki_s2_inv * delta) * dir > 0.0) {
                integ[0] = mb_state.integral_error_nms_s.x;
                torq[0] = -mb_config.kp_s_inv * errv[0] - mb_config.ki_s2_inv * integ[0];
            }
        }
        if (fabs(prop_torq[1]) > mb_config.torque_limit_nm) {
            double dir = (prop_torq[1] > 0.0) ? 1.0 : -1.0;
            double delta = integ[1] - mb_state.integral_error_nms_s.y;
            if ((-mb_config.ki_s2_inv * delta) * dir > 0.0) {
                integ[1] = mb_state.integral_error_nms_s.y;
                torq[1] = -mb_config.kp_s_inv * errv[1] - mb_config.ki_s2_inv * integ[1];
            }
        }
        if (fabs(prop_torq[2]) > mb_config.torque_limit_nm) {
            double dir = (prop_torq[2] > 0.0) ? 1.0 : -1.0;
            double delta = integ[2] - mb_state.integral_error_nms_s.z;
            if ((-mb_config.ki_s2_inv * delta) * dir > 0.0) {
                integ[2] = mb_state.integral_error_nms_s.z;
                torq[2] = -mb_config.kp_s_inv * errv[2] - mb_config.ki_s2_inv * integ[2];
            }
        }
    }

    if (torq[0] > mb_config.torque_limit_nm)
        torq[0] = mb_config.torque_limit_nm;
    else if (torq[0] < -mb_config.torque_limit_nm)
        torq[0] = -mb_config.torque_limit_nm;
    else {
    }
    if (torq[1] > mb_config.torque_limit_nm)
        torq[1] = mb_config.torque_limit_nm;
    else if (torq[1] < -mb_config.torque_limit_nm)
        torq[1] = -mb_config.torque_limit_nm;
    else {
    }
    if (torq[2] > mb_config.torque_limit_nm)
        torq[2] = mb_config.torque_limit_nm;
    else if (torq[2] < -mb_config.torque_limit_nm)
        torq[2] = -mb_config.torque_limit_nm;
    else {
    }

    err_norm = sqrt(errv[0] * errv[0] + errv[1] * errv[1] + errv[2] * errv[2]);

    if (mb_state.mode == MB_BIAS) {
        if (err_norm <= mb_config.enter_error_nms) {
            mb_state.settled = mb_state.settled + 1U;
        } else {
            mb_state.settled = 0U;
        }
        if (mb_state.settled >= mb_config.settle_cycles) {
            mb_state.mode = MB_HOLD;
            mb_state.settled = 0U;
        }
    } else if (mb_state.mode == MB_HOLD) {
        if (err_norm >= mb_config.exit_error_nms) {
            mb_state.mode = MB_BIAS;
            mb_state.settled = 0U;
        }
    } else {
    }

    mb_state.integral_error_nms_s = (adcs_vec3_t){integ[0], integ[1], integ[2]};

    mb_output.mode = mb_state.mode;
    mb_output.settled = mb_state.settled;
    mb_output.saturation_mask = mask;
    mb_output.momentum_nms = momentum;
    mb_output.commanded_target_nms = mb_state.commanded_target_nms;
    mb_output.error_nms = (adcs_vec3_t){errv[0], errv[1], errv[2]};
    mb_output.integral_error_nms_s = (adcs_vec3_t){integ[0], integ[1], integ[2]};
    mb_output.torque_nm = (adcs_vec3_t){torq[0], torq[1], torq[2]};
}
